CREATE TYPE "Role" AS ENUM ('ADMIN','COMMERCIAL','LEGAL');
CREATE TYPE "TaskStatus" AS ENUM ('PENDING','IN_PROGRESS','DONE');
CREATE TYPE "PublicationStatus" AS ENUM ('PENDING','APPROVED','REJECTED');
CREATE TYPE "ProposalStage" AS ENUM ('LEAD','MEETING','PROPOSAL','WON','LOST');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"role" "Role" NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"isDemo" BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "Client" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"taxId" TEXT,"email" TEXT,"phone" TEXT,"notes" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"isDemo" BOOLEAN NOT NULL DEFAULT false,"remoteLeadId" TEXT UNIQUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Service" ("id" TEXT PRIMARY KEY,"clientId" TEXT NOT NULL REFERENCES "Client"("id"),"name" TEXT NOT NULL,"monthlyFee" DECIMAL(12,2) NOT NULL,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3));
CREATE TABLE "Proposal" ("id" TEXT PRIMARY KEY,"clientId" TEXT NOT NULL REFERENCES "Client"("id"),"title" TEXT NOT NULL,"value" DECIMAL(12,2) NOT NULL,"stage" "ProposalStage" NOT NULL DEFAULT 'LEAD',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Publication" ("id" TEXT PRIMARY KEY,"fingerprint" TEXT NOT NULL UNIQUE,"sourceId" TEXT NOT NULL,"sourceUrl" TEXT,"caseNumber" TEXT,"court" TEXT,"publishedAt" TIMESTAMP(3),"content" TEXT NOT NULL,"nature" TEXT NOT NULL,"suggestion" TEXT NOT NULL,"status" "PublicationStatus" NOT NULL DEFAULT 'PENDING',"clientId" TEXT REFERENCES "Client"("id"),"isDemo" BOOLEAN NOT NULL DEFAULT false,"reviewedBy" TEXT,"reviewedAt" TIMESTAMP(3),"reviewNote" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Task" ("id" TEXT PRIMARY KEY,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"status" "TaskStatus" NOT NULL DEFAULT 'PENDING',"dueAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"clientId" TEXT REFERENCES "Client"("id"),"assigneeId" TEXT NOT NULL REFERENCES "User"("id"),"isDemo" BOOLEAN NOT NULL DEFAULT false,"notionPageId" TEXT UNIQUE,"publicationId" TEXT UNIQUE REFERENCES "Publication"("id"),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Case" ("id" TEXT PRIMARY KEY,"clientId" TEXT NOT NULL REFERENCES "Client"("id"),"number" TEXT NOT NULL,"court" TEXT NOT NULL,"kind" TEXT NOT NULL,"status" TEXT NOT NULL,UNIQUE("clientId","number"));
CREATE TABLE "Document" ("id" TEXT PRIMARY KEY,"clientId" TEXT REFERENCES "Client"("id"),"name" TEXT NOT NULL,"url" TEXT NOT NULL,"remoteId" TEXT NOT NULL UNIQUE,"kind" TEXT NOT NULL,"modifiedAt" TIMESTAMP(3) NOT NULL,"isDemo" BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "Meeting" ("id" TEXT PRIMARY KEY,"clientId" TEXT REFERENCES "Client"("id"),"title" TEXT NOT NULL,"url" TEXT NOT NULL,"happenedAt" TIMESTAMP(3) NOT NULL,"remoteId" TEXT NOT NULL UNIQUE,"isDemo" BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "Outbox" ("id" TEXT PRIMARY KEY,"taskId" TEXT NOT NULL UNIQUE REFERENCES "Task"("id"),"status" TEXT NOT NULL DEFAULT 'PENDING',"attempts" INTEGER NOT NULL DEFAULT 0,"nextAttemptAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lockedUntil" TIMESTAMP(3),"lastError" TEXT,"sentAt" TIMESTAMP(3));
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY,"actorId" TEXT NOT NULL,"action" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT NOT NULL,"detail" TEXT NOT NULL,"isDemo" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "TimelineEvent" ("id" TEXT PRIMARY KEY,"clientId" TEXT NOT NULL REFERENCES "Client"("id"),"title" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SyncState" ("key" TEXT PRIMARY KEY,"cursor" TEXT,"lastSuccessAt" TIMESTAMP(3),"lastError" TEXT,"lockedUntil" TIMESTAMP(3));
CREATE INDEX "Client_isDemo_active_idx" ON "Client"("isDemo","active");
CREATE INDEX "Task_isDemo_status_dueAt_idx" ON "Task"("isDemo","status","dueAt");
CREATE INDEX "Publication_isDemo_status_idx" ON "Publication"("isDemo","status");
CREATE INDEX "AuditLog_isDemo_createdAt_idx" ON "AuditLog"("isDemo","createdAt");
